function migrateGameData(input,gameId){
  const data=input&&typeof input==='object'?input:{};
  const base=baseGameData(gameId);
  const settings={...base.settings,...(data.settings||{}),labels:{...base.settings.labels,...(data.settings?.labels||{})}};
  const withGameId=list=>(Array.isArray(list)?list:[]).map(record=>({...record,gameId}));
  const factions=withGameId(Array.isArray(data.factions)?data.factions:base.factions).map(faction=>normalizeFaction(faction,gameId));
  const roles=withGameId(data.roles).map(role=>normalizeRole(role,gameId));
  const players=withGameId(data.players).map(player=>normalizePlayer(player,gameId));
  const actions=withGameId(data.actions);
  let abilities=Array.isArray(data.abilities)&&data.abilities.length?withGameId(data.abilities):base.abilities;
  const templates=standardAbilities();
  abilities=abilities.map(ability=>{
    const revisions=Array.isArray(ability.revisions)?ability.revisions:[];
    const template=ability.builtIn?templates.find(item=>[ability.defaultName,ability.name,...revisions.map(revision=>revision.name)].some(name=>normalized(name)===normalized(item.name))):null;
    const globalMetadata=template?{resolutionCategory:template.resolutionCategory,resolutionPriority:template.resolutionPriority,resolutionTiming:template.resolutionTiming,activePassive:template.activePassive,standardAbilityId:template.standardAbilityId}:{};
    const updatedDefault=template&&revisions.length===0?{category:template.category,definition:template.definition,phase:template.phase,mechanics:[...template.mechanics],targeting:{...template.targeting}}:{};
    const normalizedAbility={...ability,...updatedDefault,...globalMetadata,gameId,defaultName:ability.builtIn?(ability.defaultName||template?.name||ability.name):undefined,mechanics:Array.isArray(updatedDefault.mechanics??ability.mechanics)?updatedDefault.mechanics??ability.mechanics:[],mechanicalStatements:Array.isArray(ability.mechanicalStatements)?ability.mechanicalStatements:Array.isArray(ability.understanding?.mechanics)?ability.understanding.mechanics:[],revisions};normalizedAbility.understanding=normalizeAbilityUnderstanding(normalizedAbility);normalizedAbility.targeting=normalizedAbility.understanding.targeting;return normalizedAbility;
  });
  const existingNames=new Set(abilities.map(ability=>normalized(ability.defaultName||ability.name)));abilities.push(...templates.filter(template=>!existingNames.has(normalized(template.name))).map(template=>({...template,gameId})));
  const rules=withGameId(data.rules).map((rule,index)=>normalizeRule(rule,gameId,index));
  const documentAnalysis=data.documentAnalysis&&typeof data.documentAnalysis==='object'?{...data.documentAnalysis}:{};documentAnalysis.mechanicSchemaVersion=1;documentAnalysis.mechanicsReview=mechanicsReviewQueue({game:{id:gameId,name:''},roles,abilities});return {version:11,gameId,lastSavedAt:data.lastSavedAt||null,settings,documentAnalysis,factions,roles,players,actions,rules,abilities,history:withGameId(data.history),imports:Array.isArray(data.imports)?data.imports:[]};
}
