  const name=$('roleName').value.trim(),factionId=$('roleFaction').value,roleType=$('roleType').value,abilities=state.abilities.filter(ability=>selectedRoleAbilityIds.has(ability.id)),slotCount=Math.trunc(Number($('roleSlotCount').value));
